#!/usr/bin/env python3
"""Score images generated by ear-amaze's own `infer/infer_janus.py`, using the
SAME AmazeMetrics used for PT/DiT, and log the same general/OOD/per-shape/
per-size tables to wandb.

Usage (one shape per invocation):
    python score_amaze_images.py maze --gen-dir runs/ft_janus_square/generated \
        --geometry square --run-name ft_janus_square_maze --wandb-project amaze_final
"""
from __future__ import annotations

import argparse
import json
import logging
import re
import sys
from pathlib import Path

import torch
from PIL import Image
from torchvision import transforms
import torchvision.utils as vutils

TRM_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(TRM_ROOT))

from datasets.amaze_dataset import AmazeDataset
from eval.amaze_eval import (
    AmazeMetrics,
    MAZE_GEOMETRIES,
    MAZE_OOD_SCALES,
    MAZE_SCALES,
    QUEEN_OOD_SCALES,
    QUEEN_SCALES,
    build_maze_result,
    build_queens_result,
    log_tables,
    queens_sample_key,
)

logger = logging.getLogger(__name__)
logging.basicConfig(level="INFO")

# Resolution the generations are scored at. PT/DiT genuinely produce 144px, but a
# Janus/Bagel generation is usually larger, and shrinking it here throws away detail
# the scorer could have used (AmazeMetrics upsamples to the cell_map's native size
# either way). Override with --image-size; score_combo warns when it is downscaling.
IMAGE_SIZE = 144


def _set_image_size(size: int) -> None:
    global IMAGE_SIZE
    IMAGE_SIZE = int(size)


def _to_tensor(image: Image.Image) -> torch.Tensor:
    return transforms.Compose([
        transforms.Resize((IMAGE_SIZE, IMAGE_SIZE),
                          interpolation=transforms.InterpolationMode.BICUBIC, antialias=True),
        transforms.ToTensor(),
    ])(image)

# infer_janus.py names its output {prefix}_{id}_attempt{NNN}.png, where prefix is
# "{w}x{h}" (maze), "layers_{N}" (circle) or "0x0" (queens).
#
# Splitting this generically is impossible: BOTH halves can contain underscores
# ("layers_9" on the left, "level_7_000001" on the right), so a greedy prefix
# steals the id's leading fields and a lazy one steals the prefix's. Queens ids
# look exactly like that, which silently reduced every queens score to 0.
# So: when the prefix is known (maze) anchor on it; otherwise (queens) rely on
# that prefix having no underscore.
_QUEENS_ATTEMPT_RE = re.compile(r"^(?P<prefix>[^_]+)_(?P<id>.+)_attempt(?P<attempt>\d+)\.png$")


def _attempt_re(prefix: str | None) -> re.Pattern:
    if prefix is None:
        return _QUEENS_ATTEMPT_RE
    return re.compile(rf"^(?P<prefix>{re.escape(prefix)})_(?P<id>.+)_attempt(?P<attempt>\d+)\.png$")


def _load_img(path: Path) -> tuple[torch.Tensor, tuple[int, int] | None]:
    """(tensor, native size) — a missing file yields a blank image and size None."""
    if path is not None and path.exists():
        image = Image.open(path).convert("RGB")
        return _to_tensor(image), image.size
    return torch.zeros(3, IMAGE_SIZE, IMAGE_SIZE), None


def _maze_combo(geometry: str, scale: int) -> str:
    return f"{geometry}_n{scale}"


def _maze_parquet(data_root: Path, geometry: str, scale: int) -> Path:
    return data_root / "maze" / geometry / f"n{scale}_test.parquet"


def _build_id_index(ds) -> dict:
    """Map each puzzle's stable `id` (the value infer_janus.py used to name
    generated files) to its positional index in this AmazeDataset instance.

    Raises KeyError loudly if `id` isn't present in metadata, rather than
    silently mis-aligning scores to the wrong ground truth.
    """
    id_to_idx = {}
    for i in range(len(ds)):
        meta = ds[i].metadata if ds[i].metadata is not None else {}
        pid = meta.get("id")
        if pid is None:
            raise KeyError(
                f"AmazeDataset item {i} has no 'id' in .metadata - can't align "
                f"generated filenames (named by id) to this dataset's rows. "
                f"Check datasets/amaze_dataset.py for the actual id field name "
                f"and update _build_id_index()."
            )
        id_to_idx[str(pid)] = i
    return id_to_idx


def _discover_generated(gen_dir: Path, prefix: str | None) -> dict:
    """Group infer_janus.py's flat output by puzzle id.

    ``prefix=None`` matches every ``*_attempt*.png`` regardless of the size
    prefix - used for queens, where infer_janus can't read a maze_config and
    names every board "0\u00d70_<id>_attempt...", so scale is recovered by
    matching ``id`` against each per-scale parquet, not by the filename.

    Returns {id: {attempt_idx (0-based): file_path}}
    """
    pattern = "*_attempt*.png" if prefix is None else f"{prefix}_*_attempt*.png"
    matcher = _attempt_re(prefix)
    by_id: dict = {}
    for f in gen_dir.glob(pattern):
        m = matcher.match(f.name)
        if not m:
            continue
        pid = m.group("id")
        attempt_idx = int(m.group("attempt")) - 1  # infer_janus.py writes attempt+1 (1-indexed)
        by_id.setdefault(pid, {})[attempt_idx] = f
    return by_id


def score_combo(gen_dir: Path, combo: str, parquet: Path, task: str, device, k: int,
                samples_dir: Path, saved_counter: list, prefix: str | None):
    if not parquet.exists():
        raise FileNotFoundError(f"test parquet not found: {parquet}")

    ds = AmazeDataset(str(parquet), split="test", image_size=IMAGE_SIZE,
                      condition_field="m_original_img", target_field="sol_img",
                      num_channels=3, include_metadata=True)
    id_to_idx = _build_id_index(ds)

    # Maze: prefix is the size ("9\u00d79", Unicode '\u00d7' not 'x') or "layers_N" (circle).
    # Queens: prefix=None -> match every *_attempt*.png and separate scales by `id`.
    by_id = _discover_generated(gen_dir, prefix)
    if not by_id:
        logger.warning(f"No generated files found for combo={combo} (prefix={prefix}) in {gen_dir}")

    scorer = AmazeMetrics(device=device, task=task)
    rows, sample_pair = [], None
    missing_attempts = 0
    native_sizes: set = set()

    # Order by original row index so per-combo tables read the same as before,
    # even though iteration is keyed by id rather than a contiguous range.
    ordered_ids = sorted(
        (pid for pid in by_id if pid in id_to_idx),
        key=lambda pid: id_to_idx[pid],
    )
    missing_ids = [pid for pid in by_id if pid not in id_to_idx]
    if missing_ids and prefix is not None:
        logger.warning(
            f"{len(missing_ids)} generated ids for combo={combo} were not found "
            f"in {parquet} (e.g. {missing_ids[:5]}) - skipped."
        )
    # Queens matches every scale's files against every per-scale parquet, so most ids
    # SHOULD be missing here. Matching none of them is the real failure, and used to
    # be reported as a clean 0.0 for every metric.
    if by_id and not ordered_ids:
        logger.error(
            f"combo={combo}: none of the {len(by_id)} generated ids exist in "
            f"{parquet.name} (generated e.g. {list(by_id)[:3]}, "
            f"parquet e.g. {list(id_to_idx)[:3]}). Scoring nothing - were the images "
            f"generated from a different version of this dataset?"
        )

    chunk = 64
    for start in range(0, len(ordered_ids), chunk):
        batch_ids = ordered_ids[start:start + chunk]
        n = len(batch_ids)
        inputs = torch.zeros(n, k, 3, IMAGE_SIZE, IMAGE_SIZE)
        puzzles = []

        for pi, pid in enumerate(batch_ids):
            puzzle = ds[id_to_idx[pid]]
            puzzles.append(puzzle)
            attempts = by_id[pid]
            for a in range(k):
                inputs[pi, a], native = _load_img(attempts.get(a))
                if native is None:
                    missing_attempts += 1
                else:
                    native_sizes.add(native)

            if saved_counter[0] < 25:
                cond = puzzle.spatial_conditions
                if cond is not None:
                    gen = inputs[pi, 0]
                    combined_img = torch.cat([cond.cpu(), gen.cpu()], dim=2)
                    out_img_path = samples_dir / f"{saved_counter[0]:02d}_{combo}_id{pid}.png"
                    vutils.save_image(combined_img, out_img_path)
                    saved_counter[0] += 1

        if sample_pair is None and puzzles:
            cond = puzzles[0].spatial_conditions
            sample_pair = {"generated": inputs[0, 0].clone(),
                           "condition": cond.detach().cpu() if cond is not None else None}

        metadata = [p.metadata if p.metadata is not None else {} for p in puzzles]

        for rec in scorer.compute_and_accumulate_metrics(inputs, metadata):
            pass_at_k = rec[f"pass_at_{k}"] if k > 1 else rec["pass"]
            rows.append({
                "violation": rec["background_violation"], "coverage": rec["gt_cell_coverage"],
                "mse_inside": rec["mse_inside"], "mse_outside": rec["mse_outside"],
                "pass1": rec["pass"], "pass5": pass_at_k,
            })

    # A missing attempt is scored as a blank image, i.e. a failed attempt. That is
    # defensible, but it must not be silent: it drags Pass@K down while leaving the
    # violation column looking clean.
    if missing_attempts:
        logger.warning(
            f"combo={combo}: {missing_attempts} of {len(ordered_ids) * k} attempts had no "
            f"image file and were scored as blank (each counts as a failed attempt)."
        )
    if native_sizes and max(max(wh) for wh in native_sizes) > IMAGE_SIZE:
        logger.warning(
            f"combo={combo}: generations are {sorted(native_sizes)[-1][0]}px but scored at "
            f"{IMAGE_SIZE}px — detail is being discarded. Pass --image-size to score closer "
            f"to native."
        )
    return rows, sample_pair


def _print_row(label, agg):
    print(f"\n== {label} ==")
    print(f"  viol {agg['violation']*100:.2f}%  cov {agg['coverage']*100:.2f}%  "
          f"mseIn {agg['mse_inside']:.4f}  mseOut {agg['mse_outside']:.4f}  "
          f"P@1 {agg['pass1']*100:.2f}%  P@5 {agg['pass5']*100:.2f}%")


def _maze_prefix(geometry, scale):
    # Mirror infer_janus.py's filename prefix: "layers_N" for circle, else
    # "{w}\u00d7{h}" with the Unicode MULTIPLICATION SIGN (not ASCII 'x').
    return f"layers_{scale}" if geometry == "circle" else f"{scale}\u00d7{scale}"


def _score_maze(gen_dir, geometry, data_root, device, k, samples_dir, saved_counter):
    per_combo, ood_combo, samples = {}, {}, {}
    for s in MAZE_SCALES:
        combo = _maze_combo(geometry, s)
        rows, pair = score_combo(gen_dir, combo, _maze_parquet(data_root, geometry, s),
                                  "maze", device, k, samples_dir, saved_counter, _maze_prefix(geometry, s))
        per_combo[f"{geometry}_{s}"] = rows
        samples[combo] = pair
    for s in MAZE_OOD_SCALES:
        combo = _maze_combo(geometry, s)
        rows, pair = score_combo(gen_dir, combo, _maze_parquet(data_root, geometry, s),
                                  "maze", device, k, samples_dir, saved_counter, _maze_prefix(geometry, s))
        ood_combo[f"{geometry}_{s}"] = rows
        samples[combo] = pair
    return build_maze_result(per_combo, ood_combo), samples


def _queens_parquet(data_root: Path, scale: int) -> Path:
    return data_root / "queens" / f"n{scale}_test.parquet"


def _score_queens(gen_dir, data_root, device, k, samples_dir, saved_counter):
    # infer_janus.py can't read a maze_config for queens, so every board is named
    # "0\u00d70_<id>_attempt...". prefix=None -> match all, split scales by `id`.
    per_scale, ood_scale, samples = {}, {}, {}
    for s in QUEEN_SCALES:
        combo = f"n{s}"
        rows, pair = score_combo(gen_dir, combo, _queens_parquet(data_root, s),
                                  "queens", device, k, samples_dir, saved_counter, None)
        per_scale[str(s)] = rows
        samples[queens_sample_key(s)] = pair
    for s in QUEEN_OOD_SCALES:
        combo = f"n{s}"
        rows, pair = score_combo(gen_dir, combo, _queens_parquet(data_root, s),
                                  "queens", device, k, samples_dir, saved_counter, None)
        ood_scale[str(s)] = rows
        samples[queens_sample_key(s)] = pair
    return build_queens_result(per_scale, ood_scale), samples


def main():
    ap = argparse.ArgumentParser(description="Score infer_janus.py-generated images with AmazeMetrics -> amaze_final.")
    ap.add_argument("task", choices=["maze", "queens"])
    ap.add_argument("--gen-dir", type=Path, required=True,
                    help="Flat output_dir from one infer_janus.py run (maze: one shape; queens: the whole run)")
    ap.add_argument("--geometry", choices=MAZE_GEOMETRIES,
                    help="maze only: shape this --gen-dir was generated with (must match --filter_shape at gen time)")
    ap.add_argument("--data-root", type=Path, default=TRM_ROOT / "data" / "amaze")
    ap.add_argument("--samples-per-puzzle", type=int, default=5)
    ap.add_argument("--image-size", type=int, default=IMAGE_SIZE,
                    help=f"resolution the generations are scored at (default {IMAGE_SIZE}; "
                         f"raise it for models that generate larger images)")
    ap.add_argument("--wandb-project", default="amaze_final")
    ap.add_argument("--run-name", required=True)
    ap.add_argument("--out-json", type=Path, default=None)
    args = ap.parse_args()

    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    k = args.samples_per_puzzle
    _set_image_size(args.image_size)

    samples_dir = args.gen_dir / "samples"
    samples_dir.mkdir(parents=True, exist_ok=True)
    saved_counter = [0]

    if args.task == "maze":
        if not args.geometry:
            ap.error("--geometry is required for task=maze")
        result, samples = _score_maze(args.gen_dir, args.geometry, args.data_root, device, k, samples_dir, saved_counter)
        _print_row(f"{args.geometry} maze overall (general)", result["overall"])
        _print_row(f"{args.geometry} maze overall (OOD)", result["overall_ood"])
        out_json = args.out_json or (args.gen_dir / f"amaze_metrics_maze_{args.geometry}.json")
    else:
        result, samples = _score_queens(args.gen_dir, args.data_root, device, k, samples_dir, saved_counter)
        _print_row("queens overall (general)", result["overall"])
        _print_row("queens overall (OOD)", result["overall_ood"])
        out_json = args.out_json or (args.gen_dir / "amaze_metrics_queens.json")

    Path(out_json).parent.mkdir(parents=True, exist_ok=True)
    with open(out_json, "w") as f:
        json.dump(result, f, indent=2)
    print(f"\nResults saved -> {out_json}")
    print(f"Sample images saved -> {samples_dir}")

    if args.wandb_project:
        import wandb
        run = wandb.init(project=args.wandb_project, name=args.run_name, resume="allow")
        try:
            log_tables(run, args.task, result, samples)
            scope = args.geometry if args.task == "maze" else "all-scales"
            print(f"wandb: logged {args.task}/{scope} metrics into run {args.run_name} (project {args.wandb_project}).")
        finally:
            wandb.finish()


if __name__ == "__main__":
    main()
